'use strict';

// MODULES //

import resolveLayout from '@stdlib/blas-base-layout-resolve-str';
import isRowMajor from '@stdlib/ndarray-base-assert-is-row-major-string';
import max from '@stdlib/math-base-special-fast-max';
import format from '@stdlib/error-tools-fmtprodmsg';
import base from './base.js';


// MAIN //

/**
* Reflects the upper triangular part of a single-precision floating-point matrix `A` into the lower triangular part of another matrix `B`.
*
* @param {(integer|string)} order - storage layout of `A` and `B`
* @param {NonNegativeInteger} M - number of rows in matrix `A`
* @param {NonNegativeInteger} N - number of columns in matrix `A`
* @param {integer} k - diagonal below which to ignore
* @param {Float32Array} A - input matrix
* @param {PositiveInteger} LDA - stride of the first dimension of `A` (a.k.a., leading dimension of the matrix `A`)
* @param {Float32Array} B - output matrix
* @param {PositiveInteger} LDB - stride of the first dimension of `B` (a.k.a., leading dimension of the matrix `B`)
* @throws {TypeError} first argument must be a valid order
* @throws {RangeError} sixth argument must be a valid stride
* @throws {RangeError} eighth argument must be a valid stride
* @returns {Float32Array} `B`
*
* @example
* import Float32Array from '@stdlib/array-float32';
*
* var A = new Float32Array( [ 1.0, 2.0, 3.0, 4.0 ] );
* var B = new Float32Array( [ 0.0, 0.0, 0.0, 0.0 ] );
*
* striu2tril( 'row-major', 2, 2, 0, A, 2, B, 2 );
* // B => <Float32Array>[ 1.0, 0.0, 2.0, 4.0 ]
*
* @example
* import Float32Array from '@stdlib/array-float32';
*
* var A = new Float32Array( [ 1.0, 2.0, 3.0, 4.0 ] );
* var B = new Float32Array( [ 0.0, 0.0, 0.0, 0.0 ] );
*
* striu2tril( 'row-major', 2, 2, 1, A, 2, B, 2 );
* // B => <Float32Array>[ 0.0, 0.0, 2.0, 0.0 ]
*/
function striu2tril( order, M, N, k, A, LDA, B, LDB ) {
	var isrm;
	var sa1;
	var sa2;
	var sb1;
	var sb2;
	var sa;
	var sb;
	var l;

	l = resolveLayout( order );
	if ( l === null ) {
		throw new TypeError( format( 'invalid argument. First argument must be a valid order. Value: `%s`.', order ) );
	}
	isrm = isRowMajor( l );
	if ( isrm ) {
		sa = N; // A (M x N) has N columns
		sb = M; // B (N x M) has M columns
	} else {
		sa = M; // A (M x N) has M rows
		sb = N; // B (N x M) has N rows
	}
	if ( LDA < max( 1, sa ) ) {
		throw new RangeError( format( 'invalid argument. Sixth argument must be greater than or equal to max(1,%d). Value: `%d`.', sa, LDA ) );
	}
	if ( LDB < max( 1, sb ) ) {
		throw new RangeError( format( 'invalid argument. Eighth argument must be greater than or equal to max(1,%d). Value: `%d`.', sb, LDB ) );
	}
	if ( isrm ) {
		sa1 = LDA;
		sa2 = 1;
		sb1 = LDB;
		sb2 = 1;
	} else { // order === 'column-major'
		sa1 = 1;
		sa2 = LDA;
		sb1 = 1;
		sb2 = LDB;
	}
	return base( M, N, k, A, sa1, sa2, 0, B, sb1, sb2, 0 );
}


// EXPORTS //

export default striu2tril;
